# -*- coding: utf-8 -*-
# 第 1 批（A）：職業安全衛生法 Q0001–Q0040
# 欄位：law_id, article, difficulty, category, q_zh, opts_zh(a,b,c,d), answer, explain_zh, q_en, opts_en, explain_en
L = "OSH-01"
Q = [
(L,"第1條",1,"總則",
 "《職業安全衛生法》的立法目的為何？",
 ["防止職業災害，保障工作者安全及健康","提高事業單位生產效率並增進營運績效","規範勞資雙方工資給付及工時之標準","管理環境污染排放，維護居民生活品質"],"a",
 "第1條：為防止職業災害，保障工作者安全及健康，特制定本法。",
 "What is the legislative purpose of the Occupational Safety and Health Act?",
 ["To prevent occupational accidents and protect workers' safety and health","To improve enterprise productivity and enhance overall operating performance","To regulate wage payment and working-hour standards between employers and workers","To control environmental pollutant discharge and protect residents' living quality"],
 "Article 1: The Act is enacted to prevent occupational accidents and protect the safety and health of workers."),

(L,"第2條",1,"總則",
 "依本法第2條，「工作者」不包括下列何者？",
 ["受僱從事工作之勞工","自營作業之工作者","受指揮監督從事勞動者","單純到場參觀之訪客"],"d",
 "第2條第1款：工作者指勞工、自營作業者及其他受工作場所負責人指揮或監督從事勞動之人員。訪客未從事勞動，不屬工作者。",
 "Under Article 2, which of the following is NOT a 'worker'?",
 ["A laborer employed to perform work","A self-employed person doing work","A person working under supervision","A visitor merely touring the site"],
 "Article 2(1): 'worker' means laborers, self-employed persons and other persons performing labor under the direction or supervision of the workplace manager. A visitor performs no labor."),

(L,"第2條",1,"總則",
 "本法所稱「勞工」，指下列何者？",
 ["受僱從事工作獲致工資者","事業之經營負責人","獨立作業之技藝工作者","工作場所之出租人"],"a",
 "第2條第2款：勞工指受僱從事工作獲致工資者。",
 "Under the Act, a 'laborer' means:",
 ["A person employed to work and receiving wages","The person in charge of operating the business","An independent craftsperson","The lessor of the workplace"],
 "Article 2(2): 'laborer' means a person who is employed to work and receives wages."),

(L,"第2條",1,"總則",
 "本法所稱「雇主」，指下列何者？",
 ["工會之理事長或常務理事","事業主或事業之經營負責人","勞動檢查機構之檢查員","事業單位之職業安全衛生管理員"],"b",
 "第2條第3款：雇主指事業主或事業之經營負責人。",
 "Under the Act, 'employer' means:",
 ["The chairperson or a standing director of the labor union","The business owner or the person in charge of operating the business","An inspector employed by the labor inspection agency","The occupational safety and health administrator of the enterprise"],
 "Article 2(3): 'employer' means the business owner or the person in charge of operating the business."),

(L,"第2條",2,"總則",
 "本法所稱「職業災害」，其結果包含下列何者？",
 ["疾病、傷害或財產損失","傷害、失能或設備損壞","疾病、傷害、失能或死亡","疾病、死亡或精神壓力"],"c",
 "第2條第5款：職業災害指因勞動場所之建築物、機械、設備、原料、材料、化學品等或作業活動及其他職業上原因引起之工作者疾病、傷害、失能或死亡。",
 "Under the Act, the consequences covered by an 'occupational accident' include:",
 ["Disease, injury or property damage","Injury, disability or equipment damage","Disease, injury, disability or death","Disease, death or mental stress"],
 "Article 2(5): an occupational accident means a worker's disease, injury, disability or death caused by buildings, machinery, equipment, materials, chemicals, work activities or other occupational causes at the labor site."),

(L,"第2條",3,"總則",
 "本法所稱「作業場所」，指下列何者？",
 ["勞動契約存續中由雇主提示使勞工提供勞務之場所","接受雇主指示處理勞工事務之人所能支配管理之場所","工作場所中，從事特定工作目的之場所","自營作業者實際從事勞動之場所"],"c",
 "第2條第8款：作業場所指工作場所中，從事特定工作目的之場所。「雇主提示使勞工提供勞務之場所」為勞動場所；「處理勞工事務之人所能支配管理之場所」為工作場所。",
 "Under the Act, an 'operation site' means:",
 ["A place designated by the employer during the labor contract for the laborer to provide services","A place that can be controlled and managed by the person handling labor affairs under the employer's instruction","A place within the workplace used for a specific work purpose","A place where a self-employed person actually performs labor"],
 "Article 2(8): an operation site is a place within the workplace used for a specific work purpose. The place designated by the employer for providing services is the labor site; the place controlled by the person handling labor affairs is the workplace."),

(L,"第3條",1,"總則",
 "本法所稱中央主管機關為何？",
 ["衛生部","經濟部","勞動部","內政部"],"c",
 "第3條第1項：本法所稱主管機關，在中央為勞動部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。",
 "Which is the central competent authority under the Act?",
 ["Ministry of Health","Ministry of Economy","Ministry of Labor","Ministry of Interior"],
 "Article 3(1): the central competent authority is the Ministry of Labor; at the municipal level it is the municipal government; at the county (city) level it is the county (city) government."),

(L,"第4條",1,"總則",
 "本法的適用範圍為何？",
 ["僅適用於製造業及營造業，其他各業均不適用","僅適用於中央主管機關公告指定之特定高風險行業","適用於各業，但中央主管機關得指定公告部分規定之適用","僅適用於僱用勞工人數在三十人以上之事業單位"],"c",
 "第4條：本法適用於各業。但因事業規模、性質及風險等因素，中央主管機關得指定公告其適用本法之部分規定。",
 "What is the scope of application of the Act?",
 ["Manufacturing and construction industries only, with all other industries entirely excluded","Only specific high-risk industries designated and publicly announced by the central competent authority","All industries, though the central competent authority may designate partial application by public notice","Only enterprises employing thirty or more laborers, regardless of the industry concerned"],
 "Article 4: the Act applies to all industries; based on scale, nature and risk, the central competent authority may designate and announce partial application of the Act."),

(L,"第5條",2,"總則",
 "本法第5條規定，雇主使勞工從事工作，應在何種範圍內採取必要之預防設備或措施？",
 ["合理可行範圍內","不計成本之最高標準","勞工要求之範圍內","主管機關檢查時之範圍內"],"a",
 "第5條第1項：雇主使勞工從事工作，應在合理可行範圍內，採取必要之預防設備或措施，使勞工免於發生職業災害。",
 "Under Article 5, an employer shall take necessary preventive equipment or measures within what scope?",
 ["A reasonably practicable scope","The highest standard regardless of cost","The scope requested by the laborers","The scope examined by the competent authority during inspection"],
 "Article 5(1): the employer shall, within a reasonably practicable scope, take necessary preventive equipment or measures so that laborers are free from occupational accidents."),

(L,"第5條",2,"總則",
 "依本法第5條第2項，機械、設備、原料等物件之設計、製造或輸入者及工程之設計或施工者，應於何階段實施風險評估？",
 ["發生職業災害並經檢查後之改善階段","設計、製造、輸入或施工規劃階段","勞動檢查機構實施檢查前之準備階段","產品出廠滿三年之定期複檢階段"],"b",
 "第5條第2項：物件之設計、製造或輸入者及工程之設計或施工者，應於設計、製造、輸入或施工規劃階段實施風險評估，致力防止發生職業災害。",
 "Under Article 5(2), designers, manufacturers or importers of machinery, equipment and materials, and designers or contractors of construction works, shall conduct risk assessment at which stage?",
 ["At the improvement stage after an occupational accident has occurred","At the design, manufacturing, import or construction planning stage","At the preparation stage before the labor inspection agency inspects","At the periodic re-inspection stage three years after shipment"],
 "Article 5(2): risk assessment shall be conducted at the design, manufacturing, import or construction planning stage to prevent occupational accidents during use or construction."),

(L,"第6條",2,"安全衛生設施",
 "下列何者屬本法第6條第2項雇主應妥為規劃及採取必要安全衛生措施之事項？",
 ["防止高壓氣體及爆炸性物質引起危害之必要設備及措施","輪班、夜間工作、長時間工作等異常工作負荷促發疾病之預防","防止水患、風災、火災或地震引起危害之設備及措施","防止採石、採掘及沉箱作業引起危害之設備及措施"],"b",
 "第6條第2項四款：重複性作業促發肌肉骨骼疾病之預防、異常工作負荷促發疾病之預防、執行職務遭受不法侵害之預防、避難急救休息等事項。其餘選項屬第6條第1項。",
 "Which of the following falls under Article 6(2), matters the employer shall properly plan and take necessary safety and health measures for?",
 ["Preventing hazards arising from high-pressure gas and explosive substances at the operation site","Preventing diseases induced by abnormal workloads such as shift work, night work and long working hours","Preventing hazards caused by floods, windstorms, fires or earthquakes at the operation site","Preventing hazards arising from quarrying, excavation and pneumatic caisson operations"],
 "Article 6(2) lists four items: musculoskeletal disorders from repetitive work, diseases induced by abnormal workloads, unlawful physical or mental harm by others, and evacuation/first aid/rest. The other options fall under Article 6(1)."),

(L,"第6條",2,"安全衛生設施",
 "本法第6條第2項第3款要求雇主對「執行職務因他人行為遭受身體或精神不法侵害之預防」，除採取措施外尚應建立何種程序？",
 ["申訴、調查及處理程序","罷工、協商及調解程序","懲戒、解僱及申覆程序","投保、理賠及給付程序"],"a",
 "第6條第2項第3款：執行職務因他人行為遭受身體或精神不法侵害之預防，並建立申訴、調查及處理程序。",
 "Under Article 6(2)(3), for preventing physical or mental unlawful harm by others during the performance of duties, the employer shall also establish what procedures?",
 ["Complaint, investigation and handling procedures","Strike, negotiation and mediation procedures","Discipline, dismissal and appeal procedures","Insurance, claim and benefit payment procedures"],
 "Article 6(2)(3): prevention of unlawful physical or mental harm by others while performing duties, and establishment of complaint, investigation and handling procedures."),

(L,"第6條",1,"安全衛生設施",
 "本法第6條第1項第5款要求雇主應有必要之安全衛生設備及措施，以防止何種作業場所引起之危害？",
 ["有墜落、物體飛落或崩塌等之虞之作業場所","設有空調及照明設備之辦公室文書作業場所","供勞工用餐及休憩使用之員工餐廳場所","供訪客及員工停放車輛之地面停車場所"],"a",
 "第6條第1項第5款：防止有墜落、物體飛落或崩塌等之虞之作業場所引起之危害。",
 "Article 6(1)(5) requires the employer to have necessary safety and health equipment and measures to prevent hazards from what type of operation site?",
 ["Operation sites with risk of falls, falling objects or collapse","Office clerical work areas equipped with air conditioning and lighting","Staff cafeterias used by laborers for meals and rest periods","Ground-level parking lots used by employees and visitors"],
 "Article 6(1)(5): to prevent hazards from operation sites where there is a risk of falls, falling objects or collapse."),

(L,"第7條",2,"機械設備",
 "依本法第7條，對於中央主管機關指定之機械、設備或器具，其構造、性能及防護不符安全標準者，下列何種行為是被禁止的？",
 ["產製運出廠場、輸入、租賃、供應或設置","出口、轉運或於國外展覽陳列該等產品","於工作場所張貼標示或懸掛使用說明書","進行維修、保養或零件更換等相關作業"],"a",
 "第7條第1項：製造者、輸入者、供應者或雇主，對於指定之機械、設備或器具，其構造、性能及防護非符合安全標準者，不得產製運出廠場、輸入、租賃、供應或設置。",
 "Under Article 7, for machinery, equipment or tools designated by the central competent authority whose structure, performance and protection do not meet safety standards, which act is prohibited?",
 ["Manufacturing for shipment, importing, leasing, supplying or installing","Exporting, transshipping or displaying them at overseas exhibitions","Posting labels or hanging operating manuals in the workplace","Carrying out maintenance, servicing or replacement of parts"],
 "Article 7(1): manufacturers, importers, suppliers or employers shall not manufacture for shipment, import, lease, supply or install designated machinery, equipment or tools that do not meet safety standards."),

(L,"第7條",2,"機械設備",
 "依本法第7條第3項，製造者或輸入者對於符合安全標準之指定機械、設備或器具，應辦理下列何事？",
 ["向地方主管機關申請營業登記，並於產品包裝標示製造廠商名稱","於中央主管機關指定之資訊申報網站登錄，並於產品明顯處張貼安全標示","向勞動檢查機構申請竣工檢查，並於產品明顯處張貼檢查合格證","向保險公司投保產品責任保險，並於產品明顯處標示保險期間"],"b",
 "第7條第3項：符合安全標準者，應於中央主管機關指定之資訊申報網站登錄，並於其產製或輸入之產品明顯處張貼安全標示，以供識別。",
 "Under Article 7(3), for designated machinery, equipment or tools that meet safety standards, the manufacturer or importer shall:",
 ["Apply for business registration with the local competent authority and mark the manufacturer's name on the product packaging","Register on the central competent authority's designated information reporting website and affix a safety label conspicuously on the product","Apply to the labor inspection agency for a completion inspection and affix the inspection certificate conspicuously on the product","Take out product liability insurance with an insurer and affix a label showing the insured period conspicuously on the product"],
 "Article 7(3): products meeting the safety standards shall be registered on the designated information reporting website and bear a safety label in a conspicuous place for identification."),

(L,"第8條",2,"機械設備",
 "經中央主管機關公告列入型式驗證之機械、設備或器具，須符合何條件始得產製運出廠場或輸入？",
 ["經雇主指定之內部品管單位實施自主檢查合格及建檔備查","經中央主管機關認可之驗證機構實施型式驗證合格及張貼合格標章","經全國性同業公會實施產品審查合格及核發審查通過證明","經地方主管機關實施書面備查合格及公告於機關網站"],"b",
 "第8條第1項：非經中央主管機關認可之驗證機構實施型式驗證合格及張貼合格標章，不得產製運出廠場或輸入。",
 "For machinery, equipment or tools announced as subject to type certification, what condition must be met before manufacturing for shipment or import?",
 ["Passing self-inspection by an internal quality unit designated by the employer and keeping the records on file","Passing type certification by a certification body approved by the central competent authority and affixing a conformity mark","Passing a product review conducted by the national trade association and obtaining its approval certificate","Passing a documentary review by the local competent authority and being announced on that authority's official website"],
 "Article 8(1): they shall not be manufactured for shipment or imported unless type-certified by an approved certification body and affixed with a conformity mark."),

(L,"第8條",3,"機械設備",
 "依本法第8條第2項，下列何種情形得免實施型式驗證？",
 ["供國防軍事用途使用，並有國防部或其直屬機關出具證明","製造者自行評估品質良好，並有內部品管單位出具報告","已投保產品責任保險，並有保險公司出具承保證明文件","產品售價低於一定金額，並有會計師出具價格查核報告"],"a",
 "第8條第2項免驗證情形包括：依第16條或其他法律實施檢查驗證認可、供國防軍事用途並有國防部證明、限量製造供研發測試經核准、商業樣品或展覽品經核准、其他特殊情形經核准。",
 "Under Article 8(2), which of the following may be exempted from type certification?",
 ["Used for national defense purposes with a certificate issued by the Ministry of National Defense or its directly subordinate agency","Assessed as being of good quality by the manufacturer, with an inspection report issued by its internal quality control unit","Covered by product liability insurance with a certificate of coverage issued by the underwriting insurance company","Priced below a certain amount with a price verification report issued by a certified public accountant firm"],
 "Article 8(2) exemptions include: inspection/certification under Article 16 or other laws; national defense use with MND certificate; limited quantity for R&D/testing with approval; commercial samples or exhibits with approval; other special cases with approval."),

(L,"第9條",2,"機械設備",
 "依本法第9條，下列何種產品不得使用安全標示或驗證合格標章？",
 ["已完成資訊申報網站登錄且標示完整之產品","已取得型式驗證合格並張貼合格標章之產品","資訊申報網站登錄逾期或型式驗證逾期之產品","依法免驗證且已完成網站登錄之進口產品"],"c",
 "第9條第1項：對於未完成資訊申報網站登錄、未取得型式驗證合格、登錄逾期或型式驗證逾期之產品，不得使用安全標示、驗證合格標章或易生混淆之類似標示。",
 "Under Article 9, which product may NOT bear a safety label or certification mark?",
 ["A product that has completed website registration and is fully labeled","A product that has passed type certification and bears a conformity mark","A product whose website registration or type certification has expired","An imported product legally exempt from certification and duly registered"],
 "Article 9(1): safety labels, conformity marks or confusingly similar marks shall not be used on products that have not completed registration, have not passed type certification, or whose registration or certification has expired."),

(L,"第10條",1,"化學品管理",
 "依本法第10條，雇主對於具有危害性之化學品，應辦理下列何者？",
 ["標示、製備清單及揭示安全資料表，並採取必要之通識措施","全面改用進口化學品，並由供應商代為辦理通識措施","集中鎖存於專用倉庫，並由管理員定期清點數量及品項","於員工朝會口頭告知勞工，並請勞工簽名確認已知悉"],"a",
 "第10條第1項：雇主對於具有危害性之化學品，應予標示、製備清單及揭示安全資料表，並採取必要之通識措施。",
 "Under Article 10, for hazardous chemicals the employer shall:",
 ["Label them, prepare an inventory, make safety data sheets available and take necessary hazard communication measures","Switch entirely to imported chemicals and let the supplier carry out all the hazard communication measures","Lock them in a dedicated warehouse and have the storekeeper periodically count the quantities and item types","Inform the laborers verbally at the morning assembly and have each of them sign to confirm they are aware"],
 "Article 10(1): the employer shall label hazardous chemicals, prepare an inventory, make safety data sheets available and take necessary hazard communication measures."),

(L,"第10條",2,"化學品管理",
 "製造者、輸入者或供應者提供危害性化學品予事業單位前，應辦理何事？資料異動時如何處理？",
 ["予以標示及提供安全資料表；資料異動時亦同","僅需檢附出貨發票及型錄；資料異動時免再處理","僅需提供產品價格表及規格說明；異動時亦同","以電話口頭說明危害特性即可；異動時免通知"],"a",
 "第10條第2項：製造者、輸入者或供應者，提供化學品與事業單位或自營作業者前，應予標示及提供安全資料表；資料異動時，亦同。",
 "Before providing hazardous chemicals to an enterprise, what must manufacturers, importers or suppliers do, and what about when the information changes?",
 ["Label them and provide safety data sheets; the same applies when information changes","Only attach a shipping invoice and catalogue; no action needed when information changes","Only provide a price list and specification sheet; the same applies when information changes","Explain the hazards verbally by phone; no notification needed when information changes"],
 "Article 10(2): before providing chemicals to an enterprise or self-employed person, they shall label the chemicals and provide safety data sheets; the same applies when the information changes."),

(L,"第11條",2,"化學品管理",
 "依本法第11條，雇主對危害性化學品應依何種情形評估風險等級並採取分級管理措施？",
 ["健康危害、散布狀況及使用量","採購價格、品牌知名度及產地","包裝顏色、容器容量及材質","保存期限、供應商信用及付款條件"],"a",
 "第11條第1項：雇主對於前條之化學品，應依其健康危害、散布狀況及使用量等情形，評估風險等級，並採取分級管理措施。",
 "Under Article 11, based on what factors shall the employer assess the risk level of hazardous chemicals and adopt graded management?",
 ["Health hazards, dispersion conditions and quantity used","Purchase price, brand reputation and country of origin","Packaging color, container volume and material used","Shelf life, supplier credit rating and payment terms"],
 "Article 11(1): the employer shall assess the risk level based on health hazards, dispersion conditions and quantity used, and adopt graded management measures."),

(L,"第12條",1,"化學品管理",
 "對於中央主管機關定有容許暴露標準之作業場所，雇主應確保勞工之危害暴露如何？",
 ["等於標準值","低於標準值","高於標準值亦可","無需管理"],"b",
 "第12條第1項：雇主對於中央主管機關定有容許暴露標準之作業場所，應確保勞工之危害暴露低於標準值。",
 "For operation sites with permissible exposure limits set by the central competent authority, the employer shall ensure laborers' hazard exposure is:",
 ["Equal to the limit","Below the limit","Above the limit is acceptable","Not managed"],
 "Article 12(1): the employer shall ensure that laborers' hazard exposure is below the permissible exposure limit."),

(L,"第12條",2,"化學品管理",
 "依本法第12條第3項，雇主對經中央主管機關指定之作業場所，應訂定何種計畫並由何者實施監測？",
 ["作業環境監測計畫；由認可之作業環境監測機構實施","緊急應變計畫；由當地消防機關派員前往實施","品質管理計畫；由事業單位品管部門自行實施","年度預算計畫；由事業單位財務部門編列實施"],"a",
 "第12條第3項：應訂定作業環境監測計畫，並設置或委託由中央主管機關認可之作業環境監測機構實施監測。指定免經監測機構分析之項目得僱用合格監測人員辦理。",
 "Under Article 12(3), for operation sites designated by the central competent authority, the employer shall formulate what plan, and who conducts the monitoring?",
 ["A workplace environment monitoring plan; monitoring by an approved environment monitoring institution","An emergency response plan; monitoring carried out by personnel of the local fire authority","A quality management plan; monitoring carried out by the enterprise's own quality control unit","An annual budget plan; monitoring carried out by the enterprise's own finance department staff"],
 "Article 12(3): the employer shall formulate a workplace environment monitoring plan and establish or commission a monitoring institution approved by the central competent authority to conduct the monitoring."),

(L,"第12條",2,"化學品管理",
 "雇主對作業環境監測計畫及監測結果，應如何處理？",
 ["列為機密文件，不得對外公開","公開揭示，並通報中央主管機關","僅交由企業工會存查保管即可","於保存三年後銷毀避免資料外洩"],"b",
 "第12條第4項：雇主對於監測計畫及監測結果，應公開揭示，並通報中央主管機關。中央主管機關或勞動檢查機構得實施查核。",
 "How shall the employer handle the workplace environment monitoring plan and results?",
 ["Keep them as confidential documents that may not be disclosed","Publicly disclose them and report to the central competent authority","Hand them over to the enterprise union for safekeeping only","Destroy them after three years of storage to prevent leakage"],
 "Article 12(4): the employer shall publicly disclose the monitoring plan and results and report them to the central competent authority, which may conduct audits."),

(L,"第13條",2,"化學品管理",
 "製造者或輸入者對於化學物質清單以外之「新化學物質」，於製造或輸入前應完成何事？",
 ["向中央主管機關繳交化學物質安全評估報告，並經核准登記","向海關申報化學物質成分及數量，並取得放行通知","取得國際標準組織品質管理系統認證，並公告周知","於全國性報紙刊登公開廣告，並函知同業公會備查"],"a",
 "第13條第1項：對於中央主管機關公告之化學物質清單以外之新化學物質，未向中央主管機關繳交化學物質安全評估報告，並經核准登記前，不得製造或輸入含有該物質之化學品。",
 "Before manufacturing or importing a 'new chemical substance' not on the chemical substance inventory, a manufacturer or importer shall:",
 ["Submit a chemical substance safety assessment report to the central competent authority and obtain approved registration","Declare the chemical substance's composition and quantity to the customs authority and obtain a release notice","Obtain an ISO quality management system certification and publicly announce that certification to the trade","Publish a public advertisement in a national newspaper and notify the trade association for its record"],
 "Article 13(1): chemicals containing a new chemical substance shall not be manufactured or imported until a safety assessment report has been submitted and registration approved."),

(L,"第14條",2,"化學品管理",
 "依本法第14條第1項，對於經中央主管機關指定之「管制性化學品」，原則上如何？",
 ["不得製造、輸入、供應或供工作者處置、使用，但經中央主管機關許可者不在此限","得自由製造、輸入、供應或供工作者處置使用，無須經中央主管機關許可","僅須依規定標示及提供安全資料表，即得製造、輸入及供工作者使用","僅須將運作資料報請地方主管機關備查，即得製造、輸入及供工作者使用"],"a",
 "第14條第1項：對於經中央主管機關指定之管制性化學品，不得製造、輸入、供應或供工作者處置、使用。但經中央主管機關許可者，不在此限。",
 "Under Article 14(1), what is the rule for 'controlled chemicals' designated by the central competent authority?",
 ["They shall not be manufactured, imported, supplied or handled/used by workers, unless permitted by the central competent authority","They may be freely manufactured, imported, supplied or handled and used by workers without any permit from the authority","Labeling them and providing safety data sheets alone allows them to be manufactured, imported and used by workers","Reporting the operation data to the local competent authority alone allows their manufacture, import and use"],
 "Article 14(1): controlled chemicals shall not be manufactured, imported, supplied or handled/used by workers unless permitted by the central competent authority."),

(L,"第14條",2,"化學品管理",
 "對於中央主管機關指定之「優先管理化學品」，製造者、輸入者、供應者或雇主應如何辦理？",
 ["將相關運作資料報請中央主管機關備查","將相關運作資料報請地方主管機關核准","將相關運作資料報請勞動檢查機構許可","完全禁止製造使用，無須報請任何機關"],"a",
 "第14條第2項：對於中央主管機關指定之優先管理化學品，應將相關運作資料報請中央主管機關備查。",
 "For 'priority management chemicals' designated by the central competent authority, manufacturers, importers, suppliers or employers shall:",
 ["Report the relevant operation data to the central competent authority for record","Report the relevant operation data to the local competent authority for approval","Report the relevant operation data to the labor inspection agency for a permit","Stop all manufacture and use entirely, with no report to any authority"],
 "Article 14(2): relevant operation data of priority management chemicals shall be reported to the central competent authority for record."),

(L,"第15條",2,"製程安全",
 "依本法第15條，下列何種工作場所應定期實施製程安全評估並製作報告？",
 ["從事石油裂解之石化工業","一般行政辦公大樓場所","小型零售商店賣場","餐飲業廚房調理場所"],"a",
 "第15條第1項：從事石油裂解之石化工業，及從事製造、處置或使用危害性化學品數量達規定量以上之工作場所，應依規定期限定期實施製程安全評估，製作報告並採取必要之預防措施；製程修改時亦同。",
 "Under Article 15, which workplace shall periodically conduct process safety assessment and prepare a report?",
 ["Petrochemical industry engaged in petroleum cracking","A general administrative office building workplace","A small retail shop with a sales floor","A restaurant kitchen used for food preparation"],
 "Article 15(1): petrochemical plants engaged in petroleum cracking, and workplaces manufacturing, handling or using hazardous chemicals above the prescribed quantity, shall periodically conduct process safety assessment, prepare reports and take preventive measures; the same applies when the process is modified."),

(L,"第15條",2,"製程安全",
 "製程安全評估報告，事業單位應報請何機關備查？",
 ["勞動檢查機構","地方消防機關","環保機關","經濟部工業局"],"a",
 "第15條第2項：前項製程安全評估報告，事業單位應報請勞動檢查機構備查。",
 "To which agency shall the enterprise submit the process safety assessment report for record?",
 ["The labor inspection agency","The local fire authority","The environmental protection authority","The Industrial Development Bureau"],
 "Article 15(2): the process safety assessment report shall be submitted to the labor inspection agency for record."),

(L,"第15-1條",3,"工程安全",
 "依本法第15條之1，事業單位將一定規模以上之工程交付規劃、設計時，應辦理下列何者？",
 ["分析潛在施工危害，編製安全衛生圖說及規範，量化編列安全衛生費用，並製作工程規劃設計安全分析報告","分析潛在施工成本，編製工程預算書及發包文件，量化編列工程管理費用，並製作工程規劃設計成本分析報告","分析潛在施工進度，編製施工進度網圖及計畫，量化編列趕工獎金費用，並製作工程施工進度管制查核報告","分析潛在營運風險，編製營造綜合保險文件，量化編列保險費用，並製作工程保險理賠處理作業報告"],"a",
 "第15條之1第1項：應依其工程特性，分析潛在施工危害，編製安全衛生圖說及規範，量化編列安全衛生費用，並製作工程規劃設計安全分析報告。",
 "Under Article 15-1, when an enterprise commissions planning and design of a construction project above a certain scale, it shall:",
 ["Analyze potential construction hazards, prepare safety and health drawings and specifications, quantify safety and health costs, and prepare a planning and design safety analysis report","Analyze potential construction costs, prepare the project budget and tender documents, quantify project management costs, and prepare a planning and design cost analysis report","Analyze potential schedule risks, prepare the construction schedule network and plan, quantify acceleration bonus costs, and prepare a schedule control audit report","Analyze potential operating risks, prepare contractor's all-risk insurance documents, quantify insurance premium costs, and prepare an insurance claim handling report"],
 "Article 15-1(1): based on the project characteristics, analyze potential construction hazards, prepare safety and health drawings and specifications, quantify safety and health costs, and prepare a planning and design safety analysis report."),

(L,"第15-1條",3,"工程安全",
 "依本法第15條之1第2項，事業單位將工程交付施工時，應使施工者事前依工程規劃設計安全分析報告做什麼？",
 ["評估施工風險，採取必要預防設備及措施，納入施工計畫書並確實執行","評估施工成本，編列必要預備工程費用，納入工程預算書並確實執行","閱讀報告內容，於報告封面簽名確認，送交監造單位存查即可","轉交報告予監造單位，由監造單位代為評估風險並納入計畫"],"a",
 "第15條之1第2項：應使該施工者於事前依工程規劃設計安全分析報告，評估施工風險，採取必要之預防設備及措施，納入施工計畫書，並確實執行。第3項：事業單位應指派人員或委託專業機構監督及查證。",
 "Under Article 15-1(2), when commissioning construction, the enterprise shall require the contractor, based on the safety analysis report, to:",
 ["Assess construction risks, adopt necessary preventive equipment and measures, incorporate them into the construction plan and implement them","Assess construction costs, budget the necessary contingency expenses, incorporate them into the project budget and implement them","Read the report, sign the cover page to confirm receipt, and send the signed report to the supervising unit for filing","Forward the report to the supervising unit and let that unit assess the risks and incorporate them into the plan"],
 "Article 15-1(2): the contractor shall assess construction risks in advance based on the report, adopt necessary preventive equipment and measures, incorporate them into the construction plan and implement them; under paragraph 3 the enterprise shall assign personnel or a professional body to supervise and verify."),

(L,"第16條",1,"機械設備",
 "經中央主管機關指定具有危險性之機械或設備，須經何者檢查合格始得使用？",
 ["勞動檢查機構或中央主管機關指定之代行檢查機構","製造廠商依規定自行實施檢查之內部檢查單位","事業單位雇主指定之內部自動檢查人員","全國性同業公會設置之產品審查委員會"],"a",
 "第16條第1項：非經勞動檢查機構或中央主管機關指定之代行檢查機構檢查合格，不得使用；其使用超過規定期間者，非經再檢查合格，不得繼續使用。",
 "Designated dangerous machinery or equipment may be used only after passing inspection by:",
 ["The labor inspection agency or an agent inspection institution designated by the central competent authority","The inspection unit of the manufacturer that carries out self-inspection under the relevant regulations","The internal automatic inspection personnel designated by the employer of the enterprise","The product review committee established by the national trade association of the industry"],
 "Article 16(1): they shall not be used unless inspected and passed by the labor inspection agency or a designated agent inspection institution; after the prescribed period, re-inspection is required."),

(L,"第17條",2,"安全衛生設施",
 "勞工工作場所之建築物，應由何人依建築法規及本法安全衛生規定設計？",
 ["依法登記開業之建築師","職業安全衛生管理員","工地主任或工地負責人","雇主本人或其指定人員"],"a",
 "第17條：勞工工作場所之建築物，應由依法登記開業之建築師依建築法規及本法有關安全衛生之規定設計。",
 "Buildings used as laborers' workplaces shall be designed by whom, in accordance with building regulations and the safety and health provisions of the Act?",
 ["A legally registered practicing architect","An occupational safety and health administrator","The site director or the site person in charge","The employer personally or a designated person"],
 "Article 17: buildings of laborers' workplaces shall be designed by a legally registered practicing architect in accordance with building regulations and the safety and health provisions of the Act."),

(L,"第18條",1,"緊急應變",
 "工作場所有立即發生危險之虞時，雇主或工作場所負責人應如何處置？",
 ["即令停止作業，並使勞工退避至安全場所","要求勞工加快作業，儘速完成後再行退避","先通報勞動檢查機構，等待檢查員到場處理","以口頭提醒勞工小心，並繼續原有作業"],"a",
 "第18條第1項：工作場所有立即發生危險之虞時，雇主或工作場所負責人應即令停止作業，並使勞工退避至安全場所。",
 "When there is an imminent danger in the workplace, the employer or workplace manager shall:",
 ["Immediately order work to stop and have laborers withdraw to a safe place","Ask laborers to speed up the work and withdraw only after finishing","Notify the labor inspection agency first and wait for an inspector to arrive","Verbally remind laborers to be careful and continue the ongoing work"],
 "Article 18(1): when there is an imminent danger in the workplace, the employer or workplace manager shall immediately order work to stop and have laborers withdraw to a safe place."),

(L,"第18條",2,"緊急應變",
 "勞工執行職務發現有立即發生危險之虞時，得自行停止作業退避，並應如何處理？",
 ["立即向直屬主管報告","逕行離開公司不必通知","先向媒體投訴","三日內以書面通知雇主"],"a",
 "第18條第2項：勞工執行職務發現有立即發生危險之虞時，得在不危及其他工作者安全情形下，自行停止作業及退避至安全場所，並立即向直屬主管報告。",
 "When a laborer discovers an imminent danger while performing duties and stops work to withdraw, the laborer shall also:",
 ["Immediately report to the direct supervisor","Leave the company without notice","Complain to the media first","Notify the employer in writing within three days"],
 "Article 18(2): the laborer may stop work and withdraw to a safe place without endangering other workers, and shall immediately report to the direct supervisor."),

(L,"第18條",2,"緊急應變",
 "勞工依法自行停止作業退避後，雇主得否對其解僱、調職或不給付停止作業期間工資？",
 ["不得，但雇主證明勞工濫用停止作業權，經報主管機關認定並符合勞動法令者不在此限","得，雇主僅需事後將處分結果報請主管機關備查，並符合勞動法令規定即可","得，雇主得扣除停止作業當日工資，但應經勞資會議同意並報主管機關核准","得，雇主得予以記過及調職，但須經工會同意並報勞動檢查機構備查後為之"],"a",
 "第18條第3項：雇主不得對前項勞工予以解僱、調職、不給付停止作業期間工資或其他不利之處分。但雇主證明勞工濫用停止作業權，經報主管機關認定，並符合勞動法令規定者，不在此限。",
 "After a laborer lawfully stops work and withdraws, may the employer dismiss, transfer or withhold wages for the stoppage period?",
 ["No, unless the employer proves abuse of the right, confirmed by the competent authority and compliant with labor laws","Yes, the employer need only report the disciplinary outcome to the competent authority for record afterwards","Yes, the day's wages may be deducted with the consent of the labor-management conference and authority approval","Yes, a demerit and a transfer may be imposed after union consent and a filing with the labor inspection agency"],
 "Article 18(3): the employer shall not dismiss, transfer, withhold wages or impose other adverse treatment, unless the employer proves the laborer abused the right, as confirmed by the competent authority and in compliance with labor laws."),

(L,"第19條",1,"工時與健康",
 "在高溫場所工作之勞工，雇主不得使其每日工作時間超過幾小時？",
 ["四小時","六小時","八小時","十小時"],"b",
 "第19條第1項：在高溫場所工作之勞工，雇主不得使其每日工作時間超過六小時。",
 "For laborers working in high-temperature workplaces, the employer shall not make them work more than how many hours per day?",
 ["Four hours","Six hours","Eight hours","Ten hours"],
 "Article 19(1): laborers working in high-temperature workplaces shall not work more than six hours per day."),

(L,"第19條",2,"工時與健康",
 "依本法第19條，下列何種作業應規定減少勞工工作時間並在工作時間中予以適當休息？",
 ["異常氣壓作業、高架作業、精密作業、重體力勞動","一般文書作業、資料建檔作業、影印作業、會議紀錄","客服電話作業、線上客服作業、簡訊回覆、郵件處理","倉庫盤點作業、貨架整理作業、標籤黏貼、單據核對"],"a",
 "第19條第1項：異常氣壓作業、高架作業、精密作業、重體力勞動或其他對於勞工具有特殊危害之作業，亦應規定減少勞工工作時間，並在工作時間中予以適當之休息。",
 "Under Article 19, which operations require reduced working hours and appropriate rest during working hours?",
 ["Abnormal pressure work, work at height, precision work, heavy physical labor","General clerical work, data filing work, photocopying, meeting minutes","Customer service calls, online chat support, text replies, mail handling","Warehouse stocktaking, shelf tidying, label affixing, document checking"],
 "Article 19(1): abnormal pressure work, work at height, precision work, heavy physical labor and other work with special hazards shall have reduced working hours and appropriate rest."),

(L,"第20條",1,"健康管理",
 "依本法第20條，雇主於僱用勞工時應施行何種檢查？",
 ["體格檢查","特殊健康檢查","職業病鑑定","心理測驗"],"a",
 "第20條第1項：雇主於僱用勞工時，應施行體格檢查；對在職勞工應施行一般健康檢查、特別危害健康作業之特殊健康檢查及指定之特定對象與特定項目健康檢查。",
 "Under Article 20, what examination shall the employer conduct when hiring a laborer?",
 ["A physical examination","A special health examination","An occupational disease appraisal","A psychological test"],
 "Article 20(1): the employer shall conduct a physical examination upon hiring; for in-service laborers, general health examinations, special health examinations for especially hazardous work, and designated examinations for specific groups/items."),

(L,"第20條",1,"健康管理",
 "勞工體格及健康檢查之費用由何人負擔？檢查紀錄由何人保存？",
 ["費用由雇主負擔；紀錄由雇主保存","費用由勞工負擔；紀錄由勞工保存","費用由政府負擔；紀錄由醫院保存","費用由工會負擔；紀錄由工會保存"],"a",
 "第20條第2項：檢查應由認可之醫療機構之醫師為之；檢查紀錄雇主應予保存，並負擔健康檢查費用。",
 "Who bears the cost of laborers' physical and health examinations, and who keeps the records?",
 ["The employer bears the cost; the employer keeps the records","The laborer bears the cost; the laborer keeps the records","The government bears the cost; the hospital keeps the records","The union bears the cost; the union keeps the records"],
 "Article 20(2): examinations shall be performed by physicians of approved medical institutions; the employer shall keep the records and bear the cost."),
]
